CREATE DATABASE IF NOT EXISTS military_asset_management;
USE military_asset_management;

-- The application uses Hibernate ddl-auto=update and will create/maintain tables.
-- This dump also provides reference seed data. Passwords are generated by the application
-- using BCrypt, so use the application startup seed for the demo users.

ON DUPLICATE KEY UPDATE name=VALUES(name), location=VALUES(location);

ON DUPLICATE KEY UPDATE name=VALUES(name), category=VALUES(category);
